pub struct Solution;

impl Solution {
    pub fn longest_valid_parentheses(s: String) -> i32 {
        let mut max_len = 0;
        let mut stack: Vec<i32> = vec![-1];

        for (i, b) in s.bytes().enumerate() {
            let idx = i as i32;
            if b == b'(' {
                stack.push(idx);
            } else {
                stack.pop();
                if let Some(&top) = stack.last() {
                    max_len = max_len.max(idx - top);
                } else {
                    stack.push(idx);
                }
            }
        }

        max_len
    }
}

